  const latest = {};
  for (const r of rows) {
    if (!r || !r.rule_id) continue;
    const v = Number(r.version) || 0;
    if (!latest[r.rule_id] || v >= (Number(latest[r.rule_id].version) || 0)) latest[r.rule_id] = r;
  }
  return Object.values(latest);
}
